"""Adore's live-show visual direction. Shared pieces remain semantic HTML."""
from sound_cta import sound_cta

def round_cta(text, href, icon, style=''):
 return f'<a class="round-cta {style}" href="{href}"><span>{text}</span><span class="cta-arrow">{icon("diagonal")}</span></a>'

def build_home(button, icon, catalog, story, process, faq, contact, municipal):
 return f'''<section class="live-hero" aria-label="O seu próximo show"><img class="stage-photo" src="/assets/hero/titas-live.jpg" alt="Titãs em apresentação ao vivo, com palco iluminado e público em primeiro plano" width="1200" height="900" fetchpriority="high"><div class="stage-shade" aria-hidden="true"></div><div class="stage-light" aria-hidden="true"></div><div class="live-inner wrap"><h1 class="live-title"><span class="title-line">Uma canção.</span><span class="title-line">Todo mundo <span class="title-blue">junto.</span></span></h1><div class="hero-bottom"><div class="hero-copy"><p class="hero-copy-lead">Grandes artistas. No palco do seu evento.</p><p>Shows para prefeituras, festivais, igrejas e empresas. A Adore ajuda você a encontrar e contratar o artista para sua programação.</p></div>{sound_cta()}<a class="discover-link" href="#artistas"><span>Encontre seu artista</span>{icon('down')}</a></div></div><div class="live-caption wrap"><span>Titãs em cena. Artista do nosso catálogo.</span><button class="motion-toggle" type="button" aria-label="Reduzir efeitos" aria-pressed="false" hidden>Efeitos: ativados</button></div></section><section class="section lineup-section" id="artistas"><div class="wrap"><div class="lineup-intro"><h2>Quem você quer<br>ouvir de perto?</h2><div class="lineup-copy"><p>Sertanejo, forró, gospel, samba, rock e muito mais. Encontre cantores e bandas para a festa da cidade, o seu festival ou aquele encontro que já tem data marcada.</p><span>Agência de artistas em Goiânia.<br>Shows em todo o Brasil.</span></div></div>{catalog(home=True)}</div></section>{municipal()}<div class="live-ribbon" aria-hidden="true"><div class="live-scroll-text"><span>DA PRIMEIRA MÚSICA</span><svg viewBox="0 0 70 70" fill="none"><path d="M35 5v60M5 35h60M14 14l42 42M14 56l42-42" stroke="currentColor" stroke-width="8" stroke-linecap="round"/></svg><span>AO ÚLTIMO BIS</span><svg viewBox="0 0 70 70" fill="none"><path d="M35 5v60M5 35h60M14 14l42 42M14 56l42-42" stroke="currentColor" stroke-width="8" stroke-linecap="round"/></svg><span>DA PRIMEIRA MÚSICA</span></div></div>{story()}{process()}{faq()}{contact()}'''

def build_story(icon, services):
 return f'''<section class="story section" id="a-adore"><div class="wrap"><div class="story-intro"><div class="backstage-collage"><figure class="backstage-photo"><img src="/assets/hero/lauana-prado.webp" alt="Lauana Prado se apresentando, artista do catálogo Adore" width="1000" height="667" loading="lazy"><figcaption>Lauana Prado</figcaption></figure><figure class="backstage-inset"><img src="/assets/hero/joao-gomes.webp" alt="João Gomes cantando, artista do catálogo Adore" width="800" height="1000" loading="lazy"><figcaption>João Gomes</figcaption></figure><div class="experience-note"><strong>15+</strong><span>anos de<br>estrada</span></div></div><div class="backstage-copy"><h2>Entre a sua ideia<br>e o palco,<br>tem a Adore.</h2><p>Há mais de 15 anos, a Adore Shows aproxima artistas e contratantes. Atendemos prefeituras, produtores, igrejas e empresas, com um catálogo de diferentes estilos para cada público.</p><p>São mais de 5.000 eventos realizados ao longo dessa trajetória. Nossa equipe acompanha a contratação: da consulta de agenda e proposta ao contrato e à confirmação do show.</p><a class="text-link" href="/quem-somos/">Conheça quem faz acontecer {icon('diagonal')}</a></div></div><div class="service-heading"><h2>Cada público,<br>um encontro.</h2><p>O palco muda. O cuidado com<br>a escolha do artista continua.</p></div><div class="service-list">{''.join(f'<div class="service"><span class="service-symbol">{icon(ic)}</span><div><h3>{t}</h3><p>{d}</p></div></div>' for ic,t,d in services)}</div></div></section>'''

def build_contact(icon):
 return f'''<section class="contact-banner"><div class="wrap"><div><h2>Vamos colocar<br>esse show de pé?</h2><p>Conte sua ideia. A data, a cidade, aquele artista que não sai da sua cabeça. O próximo passo a gente conversa.</p></div><div class="contact-actions">{sound_cta('Fale com', 'a Adore', 'contact-circle')}<button class="motion-toggle" type="button" aria-label="Reduzir efeitos" aria-pressed="false" hidden>Efeitos: ativados</button></div></div></section>'''
